INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (179, 1, '기본 네트워크와 직접 만든 네트워크', '도커에 처음부터 있는 네트워크 `bridge`, `host`, `none` 과 `docker network create 이름` 으로 만든 네트워크는 무엇이 다를까요?', '만든 네트워크는 이름으로 서로 찾을 수 있어요.', NULL, NULL, '[]', 'choice', '["`docker network create` 는 기본 네트워크 세 개를 삭제한다", "사용자 정의 네트워크는 컨테이너끼리 통신할 수 없다", "`bridge`, `host`, `none` 은 도커가 기본으로 제공하는 네트워크이고, `docker network create 이름` 은 사용자 정의 네트워크를 만든다. 사용자 정의 네트워크에서는 컨테이너 이름으로 서로를 찾을 수 있다", "기본 네트워크 세 개는 `docker network ls` 에 나오지 않는다"]', 2, '컨테이너를 만들 때 `--network 이름` 으로 네트워크를 고릅니다.', NULL, NULL, NULL, NULL),
  (179, 2, '이름으로 접속되는 곳', '같은 사용자 정의 네트워크의 두 컨테이너와, 아무 옵션 없이 기본 `bridge` 에서 실행한 컨테이너가 있습니다. 컨테이너 이름(`getent hosts 이름`, `ping 이름`)은 각각 풀릴까요?', '사용자 정의 네트워크에는 이름을 알려 주는 DNS 가 있어요.', NULL, NULL, '[]', 'choice', '["모든 네트워크에서 이름이 풀린다", "같은 사용자 정의 네트워크의 컨테이너끼리는 이름이 풀리고 `ping` 도 된다. 기본 `bridge` 의 컨테이너는 다른 컨테이너의 이름을 풀지 못한다 (`getent hosts` 가 종료 코드 2)", "사용자 정의 네트워크에서는 IP 로만 접속할 수 있다", "기본 `bridge` 에서만 이름이 풀린다"]', 1, '이름이 풀리지 않으면 컨테이너를 사용자 정의 네트워크로 옮기는 것이 해결책입니다.', NULL, NULL, NULL, NULL),
  (179, 3, '--network-alias', '컨테이너를 `docker run --network-alias db --network mynet ...` 으로 실행하면 같은 네트워크의 다른 컨테이너는 이 컨테이너를 어떻게 부를 수 있을까요?', '컨테이너 이름 말고 별명이에요.', NULL, NULL, '[]', 'choice', '["컨테이너 이름 외에 별칭 `db` 로도 이름이 풀려 접속할 수 있다", "별칭은 호스트에서만 쓸 수 있다", "별칭을 쓰면 컨테이너 이름은 더 이상 풀리지 않는다", "별칭은 이미지 이름이 된다"]', 0, '`docker network inspect 이름` 으로 연결된 컨테이너를 확인할 수 있습니다.', NULL, NULL, NULL, NULL),
  (179, 4, '네트워크 격리와 connect', '`mynet2` 의 컨테이너와 `mynet` 의 컨테이너 `a` 가 있습니다. `a` 에서 `mynet2` 컨테이너의 이름이 풀릴까요? `docker network connect mynet2 a` 를 하면요? `disconnect` 하면요?', '네트워크가 다르면 서로 보이지 않아요.', NULL, NULL, '[]', 'choice', '["처음부터 모든 네트워크의 이름이 풀린다", "`connect` 하면 컨테이너가 재시작된다", "`disconnect` 하면 컨테이너가 삭제된다", "처음에는 풀리지 않는다(네트워크가 다르면 격리된다). `connect` 하면 `a` 에 네트워크 인터페이스가 하나 더 생겨(2개) 이름이 풀리고, `disconnect` 하면 인터페이스가 다시 1개가 되어 풀리지 않는다"]', 3, '실행 중인 컨테이너에 네트워크를 붙이고 뗄 수 있습니다.', NULL, NULL, NULL, NULL),
  (179, 5, '같은 네트워크에서는 -p 가 필요 없다', '같은 사용자 정의 네트워크의 서버 컨테이너가 8080 포트를 열고 있습니다. 다른 컨테이너가 접속하려면 서버를 `-p` 로 공개해야 할까요?', '-p 는 호스트에서 접속할 때 필요해요.', NULL, NULL, '[]', 'choice', '["필요하다. `-p` 가 없으면 다른 컨테이너도 접속할 수 없다", "`-p` 를 써야 이름이 풀린다", "필요 없다. 같은 네트워크에서는 `이름:8080` 으로 바로 접속된다 (`docker port` 가 비어 있어도 된다). `-p` 는 호스트(컨테이너 밖)에서 접속할 때 필요하다", "같은 네트워크에서도 IP 로만 접속할 수 있다"]', 2, '불필요한 `-p` 를 줄이면 외부에 열리는 포트가 줄어 안전합니다.', NULL, NULL, NULL, NULL),
  (179, 6, '사용 중인 네트워크 삭제', '컨테이너가 연결되어 있는 네트워크를 `docker network rm` 하면 어떻게 될까요?', '연결된 컨테이너가 있으면 지울 수 없어요.', NULL, NULL, '[]', 'choice', '["연결된 컨테이너도 함께 삭제된다", "`network ... has active endpoints` 오류로 거부된다. 연결된 컨테이너를 지우거나 `docker network disconnect` 로 뗀 뒤에 지운다", "조용히 삭제되고 컨테이너는 `none` 네트워크로 옮겨진다", "네트워크는 한 번 만들면 지울 수 없다"]', 1, '`docker network inspect 이름` 으로 연결된 컨테이너를 확인할 수 있습니다.', NULL, NULL, NULL, NULL),
  (179, 7, '--internal 네트워크', '`docker network create --internal 이름` 으로 만든 네트워크의 컨테이너에서 외부(인터넷) 주소로 `ping` 을 하면 어떻게 될까요?', '바깥으로 나가는 길이 없는 네트워크예요.', NULL, NULL, '[]', 'choice', '["외부로 나가는 통신이 막혀 응답을 받지 못한다 (`docker network inspect` 에 `Internal: true`).", "일반 네트워크와 똑같이 외부와 통신된다", "컨테이너끼리도 통신할 수 없다", "`--internal` 은 호스트에서의 접속을 허용한다"]', 0, '데이터베이스처럼 외부와 통신할 필요가 없는 컨테이너를 따로 두는 데 씁니다.', NULL, NULL, NULL, NULL),
  (179, 8, '볼륨은 컨테이너보다 오래 산다', '명명 볼륨 `vol` 에 `-v vol:/data` 로 파일을 쓰고 그 컨테이너를 삭제했습니다. 같은 볼륨을 쓰는 새 컨테이너에서 파일이 보일까요? 볼륨 정보는 어디서 볼까요?', '컨테이너와 볼륨은 따로 관리돼요.', NULL, NULL, '[]', 'choice', '["컨테이너를 지우면 볼륨도 함께 지워진다", "새 컨테이너는 항상 빈 볼륨을 받는다", "볼륨 정보는 `docker ps` 로만 볼 수 있다", "파일이 그대로 보인다 (컨테이너를 지워도 볼륨은 남는다). `docker volume ls` 로 목록을, `docker volume inspect vol` 로 `Driver`(`local`)와 `Mountpoint`(`/var/lib/docker/volumes/vol/_data` 형식)를 본다"]', 3, '`docker volume ls` 로 이름 목록을 봅니다.', NULL, NULL, NULL, NULL),
  (179, 9, '사용 중인 볼륨 삭제', '컨테이너가 사용 중인 볼륨을 `docker volume rm` 하면 어떻게 될까요?', '쓰는 컨테이너가 있으면 지울 수 없어요.', NULL, NULL, '[]', 'choice', '["볼륨이 즉시 삭제되고 컨테이너의 데이터는 사라진다", "볼륨이 읽기 전용이 된다", "`volume is in use` 오류로 거부된다. 그 볼륨을 쓰는 컨테이너를 지운 뒤에 삭제할 수 있다", "오류 없이 이름만 바뀐다"]', 2, '그 볼륨을 쓰는 컨테이너를 먼저 지운 뒤 `docker volume rm` 을 하세요.', NULL, NULL, NULL, NULL),
  (179, 10, ':ro 마운트', '`-v vol:/data:ro` 로 마운트한 컨테이너에서 파일을 읽을 때와 `echo x > /data/new` 로 쓸 때는 각각 어떻게 될까요? `--mount` 에서는 어떻게 쓸까요?', 'ro 는 read-only 예요.', NULL, NULL, '[]', 'choice', '["읽기도 쓰기도 모두 실패한다", "읽기는 되고 쓰기는 `Read-only file system` 오류로 실패한다 (종료 코드 1). `--mount type=volume,source=vol,target=/data,readonly` 도 같은 효과이다", "쓰기도 성공하지만 경고가 나온다", "`--mount` 는 읽기 전용을 지원하지 않는다"]', 1, '설정 파일처럼 컨테이너가 바꾸면 안 되는 데이터는 `:ro` 로 마운트하세요.', NULL, NULL, NULL, NULL),
  (179, 11, '볼륨을 처음 쓸 때의 초기화', '이미지의 `/app` 에 `hello.txt` 가 들어 있습니다. 비어 있는 명명 볼륨을 `-v vol2:/app` 으로, 호스트의 빈 폴더를 `-v 폴더:/app` 으로 마운트하면 `/app` 안은 각각 어떻게 보일까요? 이미 다른 파일이 든 볼륨은요?', '빈 볼륨은 이미지의 내용으로 채워져요.', NULL, NULL, '[]', 'choice', '["빈 명명 볼륨은 처음 마운트할 때 이미지의 `/app` 내용(`hello.txt`)으로 채워지고, 호스트 폴더(바인드 마운트)는 이미지 내용을 가려 빈 폴더로 보인다. 이미 내용이 있는 볼륨은 자기 내용(`f`)을 그대로 보여 주고 이미지의 `hello.txt` 는 보이지 않는다", "세 경우 모두 이미지의 `hello.txt` 가 보인다", "바인드 마운트가 이미지 내용으로 채워진다", "빈 명명 볼륨도 빈 폴더로 보인다"]', 0, '이미지에 들어 있는 초기 데이터와 마운트가 겹치는 경로는 마운트 방식에 따라 결과가 달라집니다.', NULL, NULL, NULL, NULL),
  (179, 12, '-v 와 --mount 의 차이', '호스트에 없는 폴더를 `-v 폴더:/m` 으로 마운트할 때와 `--mount type=bind,source=폴더,target=/m` 으로 마운트할 때는 어떻게 다를까요? `--mount type=volume,source=이름,...` 은?', '하나는 알아서 만들고 하나는 거부해요.', NULL, NULL, '[]', 'choice', '["`-v` 는 거부하고 `--mount` 는 만든다", "둘 다 폴더를 만들어 준다", "둘 다 거부한다", "`-v` 는 없는 호스트 폴더를 만들어 주고, `--mount type=bind` 는 `bind source path does not exist` 오류로 거부한다. `--mount type=volume,source=이름` 은 그 이름의 볼륨이 없으면 만든다"]', 3, '경로를 잘못 써서 빈 폴더가 생기는 실수를 막으려면 `--mount` 가 더 엄격합니다.', NULL, NULL, NULL, NULL),
  (179, 13, '익명 볼륨', '`docker run -v /data ...` 처럼 호스트 쪽 이름 없이 컨테이너 경로만 쓰면 어떤 볼륨이 만들어질까요? 컨테이너를 `docker rm` 하면요? `docker rm -v` 하면요?', '이름이 없으면 이름을 무작위로 지어요.', NULL, NULL, '[]', 'choice', '["이름이 `data` 인 볼륨이 만들어진다", "`docker rm` 만 해도 익명 볼륨이 지워진다", "64자의 16진수 이름을 가진 익명 볼륨이 만들어진다. `docker rm` 만 하면 볼륨이 남아 `dangling` 상태가 되고, `docker rm -v` 는 익명 볼륨도 함께 지운다", "익명 볼륨은 컨테이너가 실행 중일 때만 존재한다"]', 2, '`docker volume ls -f dangling=true` 로 어떤 컨테이너도 쓰지 않는 볼륨을 찾을 수 있습니다.', NULL, NULL, NULL, NULL),
  (179, 14, 'tmpfs', '`docker run --tmpfs /scratch:size=1m ...` 의 `/scratch` 는 어떤 특징이 있을까요?', '메모리에 만드는 파일 시스템이에요.', NULL, NULL, '[]', 'choice', '["디스크에 영구히 저장된다", "`mount` 에 `tmpfs` 로 보이는 메모리 기반 파일 시스템이며, `size=1m` 이면 1MB 까지만 써지고(3MB 를 쓰려 해도 1MB 에서 멈춘다), 컨테이너가 끝나면 내용이 사라진다. 새 컨테이너의 `/scratch` 는 비어 있다", "크기 제한이 없다", "호스트의 폴더와 연결된다"]', 1, '`mount` 로 확인하면 파일 시스템 종류가 `tmpfs` 로 나옵니다.', NULL, NULL, NULL, NULL),
  (179, 15, '네트워크 만들기', '사용자 정의 네트워크를 **만드는** `docker network` 하위 명령을 채우세요.', '"만들다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["create", "new", "make", "add"]', NULL, '만든 뒤 `docker network ls` 로 확인합니다.', '[0]', 'docker network {0} mynet', NULL, NULL),
  (179, 16, '네트워크 지정하기', '컨테이너를 실행할 때 **네트워크를 고르는** 옵션 이름을 채우세요.', '"네트워크"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["network", "net", "link", "bridge"]', NULL, '옵션을 쓰지 않으면 기본 `bridge` 에 붙습니다.', '[0]', 'docker run -d --{0} mynet alpine sleep 600', NULL, NULL),
  (179, 17, '별칭 붙이기', '같은 네트워크에서 컨테이너를 **다른 이름으로도 부르게** 하는 옵션 이름을 채우세요.', '"네트워크"와 "별칭"을 하이픈으로 이어요.', NULL, NULL, '[]', 'fill', '["network-alias", "alias", "hostname", "dns-name"]', NULL, '별칭으로도 이름이 풀립니다.', '[0]', 'docker run -d --{0} db --network mynet alpine sleep 600', NULL, NULL),
  (179, 18, '실행 중인 컨테이너에 네트워크 붙이기', '실행 중인 컨테이너를 **다른 네트워크에도 연결**하는 하위 명령을 채우세요.', '"연결하다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["connect", "attach", "join", "link"]', NULL, '떼려면 `disconnect` 를 씁니다.', '[0]', 'docker network {0} mynet2 web', NULL, NULL),
  (179, 19, '바깥과 차단', '외부로 나가는 통신이 **막힌 네트워크**를 만드는 옵션을 채우세요.', '"내부의"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["internal", "isolated", "closed", "offline"]', NULL, '`docker network inspect` 에 `Internal: true` 로 나옵니다.', '[0]', 'docker network create --{0} private', NULL, NULL),
  (179, 20, '볼륨 만들기', '명명 볼륨을 **만드는** `docker volume` 하위 명령을 채우세요.', '"만들다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["create", "new", "make", "init"]', NULL, '`docker run -v data:/path` 로도 자동으로 만들어집니다.', '[0]', 'docker volume {0} data', NULL, NULL),
  (179, 21, '읽기 전용 마운트', '`-v` 의 마지막에 붙여 **읽기 전용**으로 마운트하는 값을 채우세요.', '"read-only"의 줄임이에요.', NULL, NULL, '[]', 'fill', '["ro", "r", "readonly", "no-write"]', NULL, '쓰면 `Read-only file system` 오류가 납니다.', '[0]', 'docker run -v data:/data:{0} alpine cat /data/f', NULL, NULL),
  (179, 22, '--mount 의 읽기 전용', '`--mount` 에서 **읽기 전용**을 정하는 옵션 이름을 채우세요.', '"읽기 전용"을 한 단어로 붙인 이름이에요.', NULL, NULL, '[]', 'fill', '["readonly", "ro", "read-only", "protect"]', NULL, '`-v` 에서는 `:ro` 로 씁니다.', '[0]', 'docker run --mount type=volume,source=data,target=/data,{0} alpine true', NULL, NULL),
  (179, 23, '메모리 파일 시스템', '컨테이너에 **메모리 기반 임시 폴더**를 만드는 `run` 옵션을 채우세요.', '"임시 파일 시스템"을 줄인 이름이에요.', NULL, NULL, '[]', 'fill', '["tmpfs", "memfs", "ramdisk", "tempdir"]', NULL, '컨테이너가 끝나면 내용이 사라집니다.', '[0]', 'docker run --{0} /scratch:size=1m alpine true', NULL, NULL),
  (179, 24, '익명 볼륨까지 삭제', '컨테이너를 지울 때 **익명 볼륨도 함께** 지우는 옵션을 채우세요.', '"볼륨"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-v", "-a", "-f", "-l"]', NULL, '`-f` 는 실행 중인 컨테이너를 강제로 지우는 옵션입니다.', '[0]', 'docker rm {0} web', NULL, NULL),
  (179, 25, '볼륨 자세히 보기', '볼륨의 **드라이버와 저장 경로**를 보는 `docker volume` 하위 명령을 채우세요.', '"검사하다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["inspect", "show", "info", "describe"]', NULL, '`Mountpoint` 에 실제 저장 경로가 나옵니다.', '[0]', 'docker volume {0} data', NULL, NULL),
  (179, 26, '컨테이너끼리 이름으로 통신하기', '서버 컨테이너와 클라이언트 컨테이너가 이름으로 통신하도록 설정하고 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '네트워크 → 실행 → 이름 확인 → 접속 순서예요.', NULL, NULL, '[]', 'order', '["`docker network create mynet` 으로 사용자 정의 네트워크를 만든다", "서버와 클라이언트를 모두 `--network mynet` 으로 실행한다", "클라이언트에서 `getent hosts 서버이름` 으로 이름이 풀리는지 확인한다", "클라이언트에서 `서버이름:포트` 로 접속해 응답이 오는지 확인한다 (`-p` 는 필요 없다)"]', NULL, '기본 `bridge` 에서는 이름이 풀리지 않으니 사용자 정의 네트워크를 쓰세요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (179, 27, '볼륨에 데이터 남기고 이어 쓰기', '컨테이너를 지워도 데이터가 남는지 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '볼륨 만들기 → 쓰기 → 컨테이너 삭제 → 새 컨테이너로 확인 순서예요.', NULL, NULL, '[]', 'order', '["`docker volume create data` 로 볼륨을 만든다", "`docker run --rm -v data:/data alpine sh -c ''echo hi > /data/f''` 로 파일을 쓴다", "컨테이너를 삭제한다 (`--rm` 이면 끝나면 자동으로 삭제된다)", "새 컨테이너에서 `-v data:/data` 로 마운트해 `cat /data/f` 로 파일이 남아 있는지 확인한다"]', NULL, '볼륨을 지우려면 `docker volume rm data` 를 따로 해야 합니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (179, 28, '볼륨을 읽기 전용으로 점검하기', '데이터를 실수로 바꾸지 않게 볼륨을 읽기 전용으로 열어 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '읽기 전용 마운트 → 읽기 → 쓰기 시도 → 다시 마운트 순서예요.', NULL, NULL, '[]', 'order', '["`-v data:/data:ro` 로 컨테이너를 실행한다", "`cat /data/f` 로 파일을 읽을 수 있는지 확인한다", "쓰기를 시도해 `Read-only file system` 오류가 나는지 확인한다", "쓰기가 필요하면 `:ro` 를 빼고 다시 실행한다"]', NULL, '읽기 전용으로 마운트해도 볼륨의 데이터 자체는 그대로 남아 있습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (179, 29, '사용 중인 네트워크 정리하기', '컨테이너가 연결된 네트워크를 안전하게 지우는 순서입니다. 순서에 맞게 놓아 보세요.', '삭제 시도 → 연결 확인 → 해제 → 다시 삭제 순서예요.', NULL, NULL, '[]', 'order', '["`docker network rm 이름` 을 하고 `has active endpoints` 오류를 확인한다", "`docker network inspect 이름` 으로 연결된 컨테이너를 확인한다", "연결된 컨테이너를 지우거나 `docker network disconnect` 로 뗀다", "`docker network rm 이름` 을 다시 실행해 지워졌는지 `docker network ls` 로 확인한다"]', NULL, '`docker network ls` 에서 지운 네트워크가 사라졌는지 확인하세요.', '[0, 1, 2, 3]', NULL, NULL, NULL);
